import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
cuda_source = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>
#include <math.h>
#define BLOCK_M 8
#define BLOCK_N 4
#define WARP_SIZE 32
__global__ void flash_attention_kernel(
    const half* __restrict__ Q,
    const half* __restrict__ K,
    const half* __restrict__ V,
    half* __restrict__ O,
    int B, int H, int S, int D)
{
    int warp_id = threadIdx.x / WARP_SIZE;
    int lane_id = threadIdx.x % WARP_SIZE;
    int q_tiles = (S + BLOCK_M - 1) / BLOCK_M;
    int tile_idx = blockIdx.x % q_tiles;
    int bh = blockIdx.x / q_tiles;
    int b = bh / H;
    int h = bh % H;
    int block_q_start = tile_idx * BLOCK_M;
    int q_idx = block_q_start + warp_id;
    bool valid_q = (q_idx < S);
    extern __shared__ half smem[];
    half* Q_tile = smem;
    half* K_tile = Q_tile + BLOCK_M * D;
    half* V_tile = K_tile + BLOCK_N * D;
    size_t bh_offset = (size_t)(b * H + h) * (size_t)S * (size_t)D;
    const half* Q_base = Q + bh_offset;
    const half* K_base = K + bh_offset;
    const half* V_base = V + bh_offset;
    half* O_base = O + bh_offset;
    for (int idx = threadIdx.x; idx < BLOCK_M * D; idx += blockDim.x) {
        int m = idx / D;
        int d = idx % D;
        int gq = block_q_start + m;
        Q_tile[idx] = (gq < S) ? Q_base[(size_t)gq * D + d] : __float2half(0.0f);
    }
    __syncthreads();
    const int D_PER_THREAD = D / WARP_SIZE;
    float q_reg[32];
    #pragma unroll
    for (int i = 0; i < D_PER_THREAD; i++) {
        q_reg[i] = __half2float(Q_tile[warp_id * D + lane_id + i * WARP_SIZE]);
    }
    float acc[32];
    #pragma unroll
    for (int i = 0; i < D_PER_THREAD; i++) acc[i] = 0.0f;
    float running_max = -INFINITY;
    float running_sum = 0.0f;
    float scale = rsqrtf((float)D);
    int num_tiles = (S + BLOCK_N - 1) / BLOCK_N;
    for (int t = 0; t < num_tiles; t++) {
        int k_start = t * BLOCK_N;
        __syncthreads();
        for (int idx = threadIdx.x; idx < BLOCK_N * D; idx += blockDim.x) {
            int n = idx / D;
            int d = idx % D;
            int gk = k_start + n;
            half kval = (gk < S) ? K_base[(size_t)gk * D + d] : __float2half(0.0f);
            half vval = (gk < S) ? V_base[(size_t)gk * D + d] : __float2half(0.0f);
            K_tile[idx] = kval;
            V_tile[idx] = vval;
        }
        __syncthreads();
        if (valid_q) {
            #pragma unroll
            for (int n = 0; n < BLOCK_N; n++) {
                int gk = k_start + n;
                if (gk >= S) continue;
                float partial = 0.0f;
                #pragma unroll
                for (int i = 0; i < D_PER_THREAD; i++) {
                    float kv = __half2float(K_tile[n * D + lane_id + i * WARP_SIZE]);
                    asm volatile ("fma.rn.f32 %0, %1, %2, %0;\n"
                                  : "+f"(partial)
                                  : "f"(q_reg[i]), "f"(kv));
                }
                #pragma unroll
                for (int offset = 16; offset > 0; offset >>= 1) {
                    int partial_bits = __float_as_int(partial);
                    int other_bits;
                    asm volatile ("shfl.sync.down.b32 %0, %1, %2, %3, %4;\n"
                                  : "=r"(other_bits)
                                  : "r"(partial_bits), "r"(offset), "r"(0x1f), "r"(0xffffffff));
                    float other = __int_as_float(other_bits);
                    partial += other;
                }
                partial = __shfl_sync(0xffffffff, partial, 0);
                float score = partial * scale;
                float new_max = fmaxf(running_max, score);
                float exp_diff_old = __expf(running_max - new_max);
                float exp_score = __expf(score - new_max);
                running_sum = running_sum * exp_diff_old + exp_score;
                #pragma unroll
                for (int i = 0; i < D_PER_THREAD; i++) {
                    acc[i] *= exp_diff_old;
                    float vv = __half2float(V_tile[n * D + lane_id + i * WARP_SIZE]);
                    asm volatile ("fma.rn.f32 %0, %1, %2, %0;\n"
                                  : "+f"(acc[i])
                                  : "f"(exp_score), "f"(vv));
                }
                running_max = new_max;
            }
        }
    }
    if (valid_q) {
        float inv_sum = 1.0f / running_sum;
        #pragma unroll
        for (int i = 0; i < D_PER_THREAD; i++) {
            float o = acc[i] * inv_sum;
            O_base[(size_t)q_idx * D + lane_id + i * WARP_SIZE] = __float2half(o);
        }
    }
}
torch::Tensor flash_attention_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
    TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(), "inputs must be CUDA tensors");
    TORCH_CHECK(Q.scalar_type() == torch::kFloat16, "inputs must be fp16");
    TORCH_CHECK(Q.is_contiguous() && K.is_contiguous() && V.is_contiguous(), "inputs must be contiguous");
    int B = Q.size(0);
    int H = Q.size(1);
    int S = Q.size(2);
    int D = Q.size(3);
    auto O = torch::empty_like(Q);
    int q_tiles = (S + BLOCK_M - 1) / BLOCK_M;
    dim3 grid((unsigned int)(B * H * q_tiles));
    dim3 block((unsigned int)(BLOCK_M * WARP_SIZE));
    size_t smem_bytes = (size_t)(BLOCK_M * D + 2 * BLOCK_N * D) * sizeof(half);
    cudaFuncSetAttribute(flash_attention_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem_bytes);
    flash_attention_kernel<<<grid, block, smem_bytes, at::cuda::getCurrentCUDAStream()>>>(
        reinterpret_cast<const half*>(Q.data_ptr<at::Half>()),
        reinterpret_cast<const half*>(K.data_ptr<at::Half>()),
        reinterpret_cast<const half*>(V.data_ptr<at::Half>()),
        reinterpret_cast<half*>(O.data_ptr<at::Half>()),
        B, H, S, D
    );
    return O;
}
'''
cpp_source = r'''
torch::Tensor flash_attention_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V);
'''
flash_attn_ext = load_inline(
    name="flash_attention_ext",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["flash_attention_forward"],
    verbose=False,
    extra_cuda_cflags=["-O3"],
)
class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        return flash_attn_ext.flash_attention_forward(
            Q.contiguous(), K.contiguous(), V.contiguous()
        )
batch_size = 2
num_heads = 32
sequence_length = 256
embedding_dimension = 1024
def get_inputs():
    Q = torch.randn(batch_size, num_heads, sequence_length, embedding_dimension, device='cuda', dtype=torch.float16)
    K = torch.randn(batch_size, num_heads, sequence_length, embedding_dimension, device='cuda', dtype=torch.float16)
    V = torch.randn(batch_size, num_heads, sequence_length, embedding_dimension, device='cuda', dtype=torch.float16)
    return [Q, K, V]
def get_init_inputs():
    return []

